1. l ≤ a ≤ r and l ≤ b ≤ r
2. a + b = a ⊕ b

The condition a + b = a ⊕ b is equivalent to saying there are no carry operations when adding a and b. This happens precisely when a & b = 0 (no two numbers have a 1 in the same bit position).

To solve this efficiently for ranges up to 10^9, I'll use digit DP on the binary representation of numbers.

```python
from functools import lru_cache

def solve(input_str):
    lines = input_str.strip().split('\n')
    t = int(lines[0])
    results = []

    for i in range(1, t + 1):
        l, r = map(int, lines[i].split())

        if l > r:
            results.append('0')
            continue

        BIT_LEN = 30

        # Get binary representations (MSB first)
        l_bits = [(l >> j) & 1 for j in range(BIT_LEN - 1, -1, -1)]
        r_bits = [(r >> j) & 1 for j in range(BIT_LEN - 1, -1, -1)]

        @lru_cache(maxsize=None)
        def count_pairs(pos, a_low, a_high, b_low, b_high):
            """
            pos: current bit position (from high to low)
            a_low: whether a is still constrained by lower bound l
            a_high: whether a is still constrained by upper bound r
            b_low: whether b is still constrained by lower bound l  
            b_high: whether b is still constrained by upper bound r
            """
            if pos < 0:
                return 1

            # Determine valid bit ranges for a at this position
            min_a = l_bits[pos] if a_low else 0
            max_a = r_bits[pos] if a_high else 1

            # Determine valid bit ranges for b at this position
            min_b = l_bits[pos] if b_low else 0
            max_b = r_bits[pos] if b_high else 1

            total = 0

            for a_bit in range(min_a, max_a + 1):
                for b_bit in range(min_b, max_b + 1):
                    # a & b must be 0, so can't have both bits as 1
                    if a_bit == 1 and b_bit == 1:
                        continue

                    # Update constraints
                    # a_low remains True only if we're still matching l
                    new_a_low = a_low and (a_bit == l_bits[pos])
                    # a_high remains True only if we're still matching r
                    new_a_high = a_high and (a_bit == r_bits[pos])
                    new_b_low = b_low and (b_bit == l_bits[pos])
                    new_b_high = b_high and (b_bit == r_bits[pos])

                    total += count_pairs(pos - 1, new_a_low, new_a_high, new_b_low, new_b_high)

            return total

        results.append(str(count_pairs(BIT_LEN - 1, True, True, True, True)))

    return '\n'.join(results)

