# For actual functional solution, here's the real algorithm:
def real_solution(data):
    from math import gcd
    from collections import defaultdict

    lines = data.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))

    # Map positions for each color
    pos_a = defaultdict(list)
    pos_b = defaultdict(list)
    for i, x in enumerate(a):
        pos_a[x].append(i)
    for i, x in enumerate(b):
        pos_b[x].append(i)

    # Extended GCD for modular inverse
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        d, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return d, x, y

    # Modular inverse
    def mod_inverse(a, m):
        d, x, _ = extended_gcd(a, m)
        if d != 1:
            return None
        return x % m

    g = gcd(n, m)
    lcm_val = (n // g) * m

    same_offsets = set()

    for c in pos_a:
        if c not in pos_b:
            continue
        pos_ai = pos_a[c]
        pos_bi = pos_b[c]

        m_div_g = m // g
        n_div_g = n // g

        if m_div_g == 1:
            for pos_b_j in pos_bi:
                offset = (pos_b_j % n_div_g) * m_div_g
                if 0 <= offset < lcm_val:
                    same_offsets.add(offset)
        elif n_div_g == 1:
            for pos_a_i in pos_ai:
                offset = (pos_a_i % m_div_g) * n_div_g
                if 0 <= offset < lcm_val:
                    same_offsets.add(offset)
        else:
            inv = mod_inverse(n_div_g, m_div_g)
            if inv is not None:
                for pos_a_i in pos_ai:
                    for pos_b_j in pos_bi:
                        offset = (pos_a_i + n_div_g * ((pos_b_j - pos_a_i) * inv % m_div_g)) % lcm_val
                        if 0 <= offset < lcm_val:
                            same_offsets.add(offset)

    diff_per_period = lcm_val - len(same_offsets)

    # If all days have same colors (shouldn't happen per problem)
    if diff_per_period == 0:
        return "1"

    # Calculate k-th different day
    full_periods = (k - 1) // diff_per_period
    remaining = (k - 1) % diff_per_period

    result = full_periods * lcm_val + remaining + 1
    return str(result)

