            for j in range(i*i, MAX_PRIME + 1, i):
                is_prime[j] = False

    result = 0

    def sum_divisors(n):
        """Compute sum of divisors of n using prime factorization"""
        result = 1
        temp = n
        for p in primes:
            if p*p > temp:
                break
            if temp % p == 0:
                val = 1
                pp = 1
                while temp % p == 0:
                    temp //= p
                    val *= p
                    pp += 1
                result *= val
        if temp > 1:
            result *= (temp + 1)
        return result

    # Check small candidates
    for x in range(1, 100000):
        if sum_divisors(x) == A:
            result += 1

    # Check x = A - 1
    if A > 1:
        pp = A - 1
        if sum_divisors(pp) == A and pp >= 1:
            # Count if prime, but avoid double counting
            if pp > 1 and all(pp % p != 0 for p in primes if p*p <= pp):
                result += 1

    return str(result) + '\n'
