def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1\n"

    n = int(lines[0])

    # Parse adjacency matrix
    A = [list(lines[i+1]) for i in range(n)]

    # Compute out-degrees
    deg = [0] * n
    for i in range(n):
        for j in range(n):
            if A[i][j] == '1':
                deg[i] += 1

    # Find vertex with maximum out-degree
    start = max(range(n), key=lambda x: deg[x])

    # Get all out-neighbors of start
    j_list = [j for j in range(n) if A[start][j] == '1']

    # Check all pairs of out-neighbors for a cycle
    for idx_j in range(len(j_list)):
        for idx_k in range(idx_j + 1, len(j_list)):
            j = j_list[idx_j]
            k = j_list[idx_k]

            # If j -> k and k -> start, we have: start -> j -> k -> start
            if A[j][k] == '1' and A[k][start] == '1':
                return f"{start + 1} {j + 1} {k + 1}\n"

            # If k -> j and j -> start, we have: start -> k -> j -> start
            if A[k][j] == '1' and A[j][start] == '1':
                return f"{start + 1} {k + 1} {j + 1}\n"

    return "-1\n"
